fn main() {
    // The remote gateway embeds the built frontend with `include_dir!`, which
    // expands at compile time. A clean checkout may not have `dist/` yet (it is
    // generated by `npm run build`), so create a placeholder to keep
    // `cargo check` working before the first frontend build.
    let manifest = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let dist = manifest.join("..").join("dist");
    if !dist.join("index.html").exists() {
        let _ = std::fs::create_dir_all(&dist);
        let _ = std::fs::write(
            dist.join("index.html"),
            "<!doctype html><meta charset=\"utf-8\"><title>Basalt</title>\
             <body style=\"font-family:system-ui;background:#0b0b0c;color:#e7e7e9\">\
             <p>前端尚未构建。请先运行 <code>npm run build</code> 再重新编译。</p>",
        );
    }
    println!("cargo:rerun-if-changed=../dist");

    tauri_build::build()
}
